    a4_shelf_12: { label: '🏷️ ورقة A4 — 12 بطاقة تسعير رفوف كبيرة (2×6 | 95×44mm)', paperType: 'a4_sheet', cols: 2, rows: 6, w: 95, h: 44, bh: 13 }
